import {translations} from './translations.mjs';
let language='de';try{const requested=new URLSearchParams(location.search).get('lang');language=requested==='en'||requested==='de'?requested:localStorage.getItem('camera.language.v1')==='en'?'en':'de';}catch{}
const escapePattern=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const fragments=Object.keys(translations).filter(k=>k.length>3).sort((a,b)=>b.length-a.length);
const pattern=new RegExp(fragments.map(escapePattern).join('|'),'g');
export function getLanguage(){return language;}
export function tr(value){const text=String(value),trim=text.trim();if(language==='de'||!trim)return text;if(translations[trim]!==undefined)return text.replace(trim,translations[trim]);return text.replace(pattern,key=>translations[key]);}
const originals=new WeakMap();
function apply(node,key,value,write){let map=originals.get(node);if(!map){map=new Map();originals.set(node,map);}let saved=map.get(key);if(!saved||value!==saved.rendered){saved={source:value,rendered:value};map.set(key,saved);}const rendered=tr(saved.source);if(rendered!==value)write(rendered);saved.rendered=rendered;}
export function translateDOM(root){if(typeof document==='undefined')return;root=root||document.body;if(!root)return;const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walk.nextNode()){if(node.parentElement?.closest('script,style,code,pre'))continue;if(node.textContent.trim())apply(node,'text',node.textContent,value=>node.textContent=value);}for(const el of [root,...root.querySelectorAll('[title],[aria-label],[placeholder],[aria-valuetext],img[alt]')])for(const attr of['title','aria-label','placeholder','aria-valuetext','alt']){const value=el.getAttribute?.(attr);if(value)apply(el,attr,value,v=>el.setAttribute(attr,v));}}
export function setLanguage(next){language=next==='en'?'en':'de';try{localStorage.setItem('camera.language.v1',language);}catch{}if(typeof document!=='undefined'){document.documentElement.lang=language;const url=new URL(location.href);if(language==='en')url.searchParams.set('lang','en');else url.searchParams.delete('lang');history.replaceState(null,'',url);document.title=tr('Kamera verstehen · Optik und Aufnahmetechnik');translateDOM();document.dispatchEvent(new CustomEvent('camera-language-change',{detail:language}));}}
if(typeof document!=='undefined'){document.documentElement.lang=language;let queued=false;const pending=new Set();new MutationObserver(records=>{for(const record of records){const node=record.target.nodeType===1?record.target:record.target.parentElement;if(node&&!node.closest('script,style,code,pre'))pending.add(node);}if(queued||!pending.size)return;queued=true;requestAnimationFrame(()=>{queued=false;const roots=[...pending];pending.clear();for(const root of roots)if(root.isConnected)translateDOM(root);});}).observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['title','aria-label','aria-valuetext','alt']});requestAnimationFrame(()=>{document.title=tr('Kamera verstehen · Optik und Aufnahmetechnik');translateDOM();});}
